	}

	var (
		log *bstNode
		min int32 = -1
	)

	go func() {
		for {
			a := <-dc.lChan
			switch a.action {
			case LOG_INSERT:
				log = log.insert(a.arg)
			case LOG_HANDLE:
				n := log.find(a.arg.CommandId)
				if n == nil {
					log = log.insert(a.arg)
					n = log.find(a.arg.CommandId)
				}
				n.ready = true
				log, min = log.inorderReady(min, func(p *GPropose) {
					dc.pChan <- p
				})
			}
		}
	}()

	return dc
}

func (c *DelayProposeChan) Write(p *GPropose) {
	if c.delay == time.Duration(0) {
		c.pChan <- p
		return
	}

	c.lChan <- logCall{
		action: LOG_INSERT,
		arg:    p,
	}
	go func() {
		time.Sleep(c.delay)
		c.lChan <- logCall{
			action: LOG_HANDLE,
			arg:    p,
		}
	}()
}

func NewLatencyTable(conf, myAddr string, addrs []string) *LatencyTable {
	if conf == "" {
		return nil
	}
	f, err := os.Open(conf)
	if err != nil {
		return nil
	}
	defer f.Close()

	myAddr = strings.Split(myAddr, ":")[0]

	dt := &LatencyTable{
		d: time.Duration(0),
	}

	s := bufio.NewScanner(f)
	for s.Scan() {
		data := strings.Split(s.Text(), " ")
		if len(data) == 2 {
			if data[0] == "uniform" {
				if d, err := time.ParseDuration(data[1]); err == nil {
					return &LatencyTable{
						d: time.Duration(int64(d) / int64(2)),
					}
				} else {
					return nil
				}
			}
		}
		if len(data) == 3 {
			d, err := time.ParseDuration(data[2])
			if err != nil {
				continue
			}
			d = time.Duration(int64(d) / int64(2))
			addr1, addr2 := data[0], data[1]
			for i := 0; i < 2; i++ {
				if myAddr != addr1 {
					addr1, addr2 = data[1], data[0]
			}
			return err
		}
		return errors.New("dead")
	}

	for {
		time.Sleep(3 * time.Second)
		new_leader = false
		for i, node := range master.nodes {
			pingNode(i, node)
		}

		if !new_leader {
			continue
		}
		if master.nextLeader != -1 {
			if beTheLeader(master.nextLeader) == nil {
				continue
			}
		}
		for i := range master.nodes {
			if beTheLeader(i) == nil {
				break
			}
		}
	}
}

func (master *Master) Register(args *defs.RegisterArgs, reply *defs.RegisterReply) error {
	master.lock.Lock()
	defer master.lock.Unlock()

	nlen := len(master.nodeList)
	index := nlen

	addrPort := fmt.Sprintf("%s:%d", args.Addr, args.Port)

	for i, ap := range master.nodeList {
		if addrPort == ap {
			index = i
			break
		}
	}

	if index == nlen {
		master.nodeList = master.nodeList[0 : nlen+1]
		master.nodeList[nlen] = addrPort
		master.addrList = master.addrList[0 : nlen+1]
		master.addrList[nlen] = args.Addr
		master.portList = master.portList[0 : nlen+1]
		master.portList[nlen] = args.Port
		master.leader[index] = false
		nlen++

		addr := args.Addr
		if addr == "" {
			addr = "127.0.0.1"
		}
		out, err := exec.Command("ping", addr, "-c 2", "-q").Output()
		if err == nil {
			master.latencies[index], _ =
				strconv.ParseFloat(strings.Split(string(out), "/")[4], 64)
			master.Printf("node %v [%v] -> %v", index,
				master.nodeList[index], master.latencies[index])
		} else {
			master.Fatal("cannot connect to " + addr)
		}
	}

	if nlen == master.N {
			r.startRecoveryForInstance(iid.replica, iid.instance)
		}
	}
}

func (r *Replica) executeCommands() {
	const SLEEP_TIME_NS = 1e6
	problemInstance := make([]int32, r.N)
	timeout := make([]uint64, r.N)
	for q := 0; q < r.N; q++ {
		problemInstance[q] = -1
		timeout[q] = 0
	}

	for !r.Shutdown {
		executed := false
		for q := int32(0); q < int32(r.N); q++ {
			for inst := r.ExecedUpTo[q] + 1; inst <= r.crtInstance[q]; inst++ {
				if r.InstanceSpace[q][inst] != nil && r.InstanceSpace[q][inst].Status == EXECUTED {
					if inst == r.ExecedUpTo[q]+1 {
						r.ExecedUpTo[q] = inst
					}
					continue
				}
				if r.InstanceSpace[q][inst] == nil || r.InstanceSpace[q][inst].Status < COMMITTED || r.InstanceSpace[q][inst].Cmds == nil {
					if inst == problemInstance[q] {
						timeout[q] += SLEEP_TIME_NS
						if timeout[q] >= COMMIT_GRACE_PERIOD {
							for k := problemInstance[q]; k <= r.crtInstance[q]; k++ {
								r.instancesToRecover <- &instanceId{q, k}
							}
							timeout[q] = 0
						}
					} else {
						problemInstance[q] = inst
						timeout[q] = 0
					}
					break
				}
				if ok := r.exec.executeCommand(int32(q), inst); ok {
					executed = true
					if inst == r.ExecedUpTo[q]+1 {
						r.ExecedUpTo[q] = inst
					}
				}
			}
		}
		if !executed {
			r.M.Lock()
			r.M.Unlock() // FIXME for cache coherence
			time.Sleep(SLEEP_TIME_NS)
		}
	}
}

