 case *Accept: dst.handleAccept(m)
 case *AcceptReply: dst.handleAcceptReply(m)
 case *Commit: dst.handleCommit(m)
 case *Prepare: dst.handlePrepare(m)
 case *PrepareReply: dst.handlePrepareReply(m)
 default:t.Fatalf("unsupported delivery %T",msg)
 }
}

func TestAuditUnseenDependencyNeverRecovered(t *testing.T) {
 leader,lo:=auditReplica(0); waiting,wo:=auditReplica(1); survivor,so:=auditReplica(2)
 leader.PreferredPeerOrder=[]int32{2,1}
 // A: replica 0'"'s write commits at replicas 0 and 2.
 leader.startPhase1(auditPut(10,\"A\"),0,0,0,nil)
