 select {case <-done:case <-time.After(time.Second):t.Fatal("executor did not stop")}
 t.Logf("after 13 seconds: B status=%d; recovery requests=%d; missing-row bound=%d",b.Status,len(waiting.instancesToRecover),waiting.crtInstance[0])
